INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁钰", "aliases": ["明景帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明景帝，正統14年（1449年）九月，朱祁钰即皇帝位。", "biography": null, "status": "draft", "id": "beac1b51-89b3-5024-bf3a-2d45bc5afe2b"}, {"name": "柯潜", "aliases": ["柯潛"], "era": "明", "birth_year": null, "death_year": null, "description": "柯潜获授进士资格。", "biography": null, "status": "draft", "id": "509913ba-3fbd-5e7f-a227-6a90191ec7e0"}, {"name": "梁珤", "aliases": ["保定伯梁珤", "梁缶"], "era": "明", "birth_year": null, "death_year": null, "description": "梁珤奉命接替王骥。", "biography": null, "status": "draft", "id": "341faff8-5d67-5789-92bc-4208bdaba6d2"}, {"name": "王来", "aliases": ["王來"], "era": "明", "birth_year": null, "death_year": null, "description": "王来奉命总督湖广、贵州军务。", "biography": null, "status": "draft", "id": "a5950c64-7d84-533e-aaaa-e6827cc87737"}, {"name": "石彪", "aliases": ["遊擊將軍石彪"], "era": "明", "birth_year": null, "death_year": null, "description": "石彪奉命巡视边防。", "biography": null, "status": "draft", "id": "b3dd53cf-1dfa-5406-ba6a-f6de1d1bab3d"}, {"name": "石亨", "aliases": ["都督石亨"], "era": "明", "birth_year": null, "death_year": null, "description": "石亨奉命统领京营兵。", "biography": null, "status": "draft", "id": "9892b251-a863-5d74-9c23-727ee42a25de"}, {"name": "石璞（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统13年（年号对照1448年）五月，石璞出任工部尚书。", "biography": null, "status": "draft", "id": "cf73a116-9338-5fa8-81a2-a33c0b3a9657"}, {"name": "王一宁", "aliases": ["王一寧"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰2年（1451年）十二月，王一宁以礼部侍郎兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "f6c6074a-4339-53a4-ad95-234af53b8770"}, {"name": "萧镃", "aliases": ["蕭鎡"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰2年（1451年）十二月，萧镃以国子监祭酒兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "4e43d816-8596-5052-bfa1-6fa5761eee83"}, {"name": "也先", "aliases": ["瓦剌太师也先"], "era": "明", "birth_year": null, "death_year": null, "description": "也先所部为明廷防备对象。", "biography": null, "status": "draft", "id": "d9af0d41-e6b4-5de2-9de3-32e0f8826f3c"}, {"name": "脱脱不花（蒙古可汗）", "aliases": ["達達可汗", "脫脫不花"], "era": "明", "birth_year": null, "death_year": null, "description": "脱脱不花（蒙古可汗）派使者到明朝。", "biography": null, "status": "draft", "id": "f7bcab60-cf00-572b-bcd5-5a8d52d60f73"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明景帝在南郊祭祀天地", "description": "景泰二年正月庚戌，明景帝朱祁钰在南郊举行祭祀天地的大典。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年正月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "49b59bfc-3dfd-513c-b9ea-fe13975d0094"}, {"title": "明廷令应黜免的朝觐官员运粮到关口之外", "description": "景泰二年正月壬子，朝廷下诏，命各地前来朝觐、经考察应予黜免的官员运粮到关口之外。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年正月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "42f37bd8-1255-50bb-b979-84b4fe36d665"}, {"title": "明廷举行祭孔仪礼", "description": "景泰二年二月辛未，明廷依释奠礼祭祀先师孔子。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年二月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "956c7d30-6c26-56fd-b804-c978203e6c4a"}, {"title": "明廷因星象异常反省政事，命廷臣议定宽恤措施", "description": "景泰二年二月辛卯，朝廷因本纪所记星象异常举行修省，下诏令廷臣逐项商议宽减负担、体恤百姓的措施。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年二月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7848f7d6-99ba-568f-b053-8736a1d96ce1"}, {"title": "明廷在京畿和山东选官劝农，授荒地并贷给耕牛和种子", "description": "景泰二年二月癸巳，朝廷命京畿和山东的巡抚举荐清廉能干的官吏专办劝农，向百姓授予荒田，出借耕牛和种子。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年二月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2350f31d-32d4-5a0c-ad78-27a2cd99a6ed"}, {"title": "明廷授予柯潜等人进士资格", "description": "景泰二年三月壬寅，朝廷授予柯潜等人不同等第的进士资格。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年三月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0281232c-17b2-577b-a30c-6fe690272c9e"}, {"title": "梁珤、王来等在平越获胜，将俘虏送到京师", "description": "景泰二年四月乙酉条记，梁珤、王来等在平越击败起事的苗民，随后把俘虏送到京师。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年四月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c0459b02-df41-555e-9c0f-9c5b1d834787"}, {"title": "瓦剌军进攻宣府马营，明廷命石彪等巡视边防", "description": "景泰二年四月甲午，瓦剌军进攻宣府马营，明廷令游击将军石彪等巡视边防。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年四月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ff2b29ec-bafa-52e8-a4d9-4ccf2424c90f"}, {"title": "石亨奉命选练京营兵，石璞总督军务", "description": "景泰二年四月乙未，朝廷命石亨从京营中选兵操练，任命尚书石璞总督军务。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年四月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fa277bd6-499e-5118-9a8b-9f5b2ec2d9aa"}, {"title": "明廷在固原修筑城墙", "description": "景泰二年五月乙巳，明廷下令在固原修筑城墙。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年五月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "78d240e7-73f3-5119-aac5-281fd88baf04"}, {"title": "本纪记六月初一预计日食未见", "description": "景泰二年六月初一，本纪记当日预计发生日食，但未见日食。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年六月戊辰朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8814bc34-7221-58c9-81ab-2ae773757355"}, {"title": "明廷命贵州各卫整治屯田", "description": "景泰二年六月己卯，明廷下诏，命贵州各卫恢复和整顿屯田事务。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年六月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b9c5f33c-4081-5da0-8fff-e99c8504e658"}, {"title": "普定、永宁、毕节多地再有起事，梁珤等留军征讨", "description": "景泰二年七月戊申，本纪记普定、永宁、毕节多地苗民再次起事，梁珤等留下军队继续征讨。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年七月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ec6fa9dc-675c-5dc5-8936-43f271ddf356"}, {"title": "南京发生地震", "description": "景泰二年八月壬申，南京发生地震。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年八月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e6342629-9608-542b-90f0-8f1d9752021f"}, {"title": "明廷恢复午朝", "description": "景泰二年八月辛巳，明廷恢复午间朝会。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年八月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "539381b5-6f1e-5a83-ad87-cbdfa236ea3a"}, {"title": "明廷下令禁止各衙门让守丧官员提前复职", "description": "景泰二年九月乙卯，明廷下令，禁止各衙门让守丧期未满的官员提前复职。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年九月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e0992727-9e0e-5013-a010-7b10e2c2510c"}, {"title": "明廷豁免山西灾区税粮", "description": "景泰二年十月己丑，朝廷免除山西受灾地区应缴的税粮。", "start_year": 1451, "end_year": 1451, "time_original": "景泰二年十月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cd28f39c-f938-5659-ae04-1a75fc926e83"}, {"title": "王一宁以礼部侍郎兼翰林学士身份入阁", "description": "景泰2年（1451年）十二月，王一宁以礼部侍郎兼翰林学士身份入阁。", "start_year": 1451, "end_year": 1451, "time_original": "景泰2年（1451年）十二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "ce24b9e6-807d-5855-8b96-ae818081f71a"}, {"title": "萧镃以国子监祭酒兼翰林学士身份入阁", "description": "景泰2年（1451年）十二月，萧镃以国子监祭酒兼翰林学士身份入阁。", "start_year": 1451, "end_year": 1451, "time_original": "景泰2年（1451年）十二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "79ba95e3-33f2-5cca-a046-963925b9030a"}, {"title": "本纪记也先杀死脱脱不花", "description": "《景帝本纪》记景泰二年十二月，瓦剌太师也先杀死可汗脱脱不花。《鞑靼传》也把两人相攻及可汗之死记在景泰二年。", "start_year": 1452, "end_year": 1452, "time_original": "景泰二年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ae77967-703c-5833-8ad1-cc704b7d7bda"}, {"title": "安南、琉球中山、瓦剌和哈密入贡", "description": "景泰二年，安南、琉球中山、瓦剌和哈密入贡。 按原历纪年，事情发生在公元1451至1452年之间。", "start_year": null, "end_year": null, "time_original": "景泰二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "055edeed-b742-516d-81be-6778ec89fe96"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

